import{_ as a,o as e,c as r,a2 as o}from"./chunks/framework.BZO4qERu.js";const q=JSON.parse('{"title":"Настройка канала QQ","description":"","frontmatter":{},"headers":[],"relativePath":"ru/integrations/channels/qq.md","filePath":"ru/integrations/channels/qq.md","lastUpdated":1792323081000}'),n={name:"ru/integrations/channels/qq.md"};function l(s,t,i,d,h,p){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="настроика-канала-qq" tabindex="-1">Настройка канала QQ <a class="header-anchor" href="#настроика-канала-qq" aria-label="Permalink to &quot;Настройка канала QQ&quot;">​</a></h1><p>Подключите своего Bot в Memoh к QQ через официальную Bot-платформу QQ: поддерживаются личные чаты, групповые чаты и треды (话题).</p><div class="warning custom-block"><p class="custom-block-title">Ограничения</p><ul><li>На один аккаунт QQ можно создать не более 5 Bot.</li><li>Ответы доставляются целыми блоками; потоковый вывод по токенам не поддерживается.</li></ul></div><h2 id="предварительные-условия" tabindex="-1">Предварительные условия <a class="header-anchor" href="#предварительные-условия" aria-label="Permalink to &quot;Предварительные условия&quot;">​</a></h2><ul><li>Аккаунт QQ для входа на <a href="https://q.qq.com/qqbot/openclaw/" target="_blank" rel="noreferrer">QQ Bot Open Platform</a>.</li></ul><h2 id="шаги" tabindex="-1">Шаги <a class="header-anchor" href="#шаги" aria-label="Permalink to &quot;Шаги&quot;">​</a></h2><h3 id="_1-создаите-bot-qq" tabindex="-1">1. Создайте Bot QQ <a class="header-anchor" href="#_1-создаите-bot-qq" aria-label="Permalink to &quot;1. Создайте Bot QQ&quot;">​</a></h3><p>На платформе QQ Bot Open Platform:</p><ol><li>Откройте <a href="https://q.qq.com/qqbot/openclaw/" target="_blank" rel="noreferrer">QQ Bot Open Platform</a> и войдите с аккаунтом QQ.</li><li>Нажмите <strong>Create Bot</strong> (创建机器人) — согласование не требуется.</li><li>Скопируйте показанные на странице <strong>AppID</strong> и <strong>AppSecret</strong>. <strong>AppSecret</strong> отображается только один раз — сохраните его в надёжном месте.</li></ol><blockquote><p>Официальные ресурсы: <a href="https://q.qq.com/" target="_blank" rel="noreferrer">QQ Bot Open Platform</a> · <a href="https://bot.q.qq.com/wiki/" target="_blank" rel="noreferrer">документация QQ Bot</a></p></blockquote><h3 id="_2-добавьте-канал-в-memoh" tabindex="-1">2. Добавьте канал в Memoh <a class="header-anchor" href="#_2-добавьте-канал-в-memoh" aria-label="Permalink to &quot;2. Добавьте канал в Memoh&quot;">​</a></h3><p>В Memoh:</p><ol><li>Откройте вкладку <strong>Platforms</strong> нужного Bot.</li><li>Нажмите <strong>Add Channel</strong> и выберите <strong>QQ</strong>.</li><li>Вставьте <strong>AppID</strong> и <strong>AppSecret</strong>.</li><li>При необходимости настройте необязательные параметры: <strong>Markdown Support</strong> и <strong>Enable Input Hint</strong> включены по умолчанию.</li><li>Нажмите <strong>Save and Enable</strong>.</li></ol><h2 id="учетные-данные" tabindex="-1">Учётные данные <a class="header-anchor" href="#учетные-данные" aria-label="Permalink to &quot;Учётные данные&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Поле</th><th>Обязательное</th><th>Описание</th></tr></thead><tbody><tr><td><strong>AppID</strong></td><td>Да</td><td>Идентификатор приложения Bot; показывается на QQ Bot Open Platform при создании Bot.</td></tr><tr><td><strong>AppSecret</strong></td><td>Да</td><td>Секрет приложения Bot; показывается только один раз при создании.</td></tr><tr><td><strong>Markdown Support</strong></td><td>Нет</td><td>Включает форматирование Markdown (по умолчанию включено).</td></tr><tr><td><strong>Enable Input Hint</strong></td><td>Нет</td><td>Показывает индикатор набора текста, пока Bot готовит ответ (по умолчанию включено).</td></tr></tbody></table><h2 id="проверка" tabindex="-1">Проверка <a class="header-anchor" href="#проверка" aria-label="Permalink to &quot;Проверка&quot;">​</a></h2><p>Отправьте Bot <code>/help</code> в личном сообщении или обратитесь к нему в групповом чате через @-упоминание с <code>/help</code>. Bot ответит списком команд — это подтверждает, что канал работает.</p><h2 id="групповые-чаты" tabindex="-1">Групповые чаты <a class="header-anchor" href="#групповые-чаты" aria-label="Permalink to &quot;Групповые чаты&quot;">​</a></h2><p>Bot работает в групповых чатах QQ и в тредах (话题): чтобы получить ответ, упомяните его в группе через @.</p><h2 id="отключение-и-смена-учетных-данных" tabindex="-1">Отключение и смена учётных данных <a class="header-anchor" href="#отключение-и-смена-учетных-данных" aria-label="Permalink to &quot;Отключение и смена учётных данных&quot;">​</a></h2><p>Отключить или удалить канал можно в любой момент на вкладке <strong>Platforms</strong> нужного Bot. Чтобы сменить учётные данные, обновите <strong>AppID</strong> / <strong>AppSecret</strong> в той же панели и сохраните.</p><h2 id="faq" tabindex="-1">Частые вопросы <a class="header-anchor" href="#faq" aria-label="Permalink to &quot;Частые вопросы {#faq}&quot;">​</a></h2><h3 id="appsecret-reset" tabindex="-1">Я потерял AppSecret <a class="header-anchor" href="#appsecret-reset" aria-label="Permalink to &quot;Я потерял AppSecret {#appsecret-reset}&quot;">​</a></h3><p><strong>AppSecret</strong> показывается только один раз — при создании Bot. Повторный просмотр на QQ Bot Open Platform принудительно сбрасывает его; после сброса обновите <strong>AppSecret</strong> в Memoh и сохраните.</p>',24)])])}const g=a(n,[["render",l]]);export{q as __pageData,g as default};
